it('runs error and cleanup hooks in order after beforeSession fails', async () => {
  const session: ChatSession = {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  const failure = new Error('setup failed');
  const calls: string[] = [];
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      calls.push('provider');
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test'}), undefined, {
    hooks: {
      beforeSession: async received => {
        expect(received).toBe(session);
        calls.push('beforeSession');
        throw failure;
      },
      beforeUserInput: async (_received, message) => {
        calls.push('beforeUserInput');
        return message;
      },
      onError: async (received, error) => {
        expect({received, error}).toEqual({received: session, error: failure});
        calls.push('onError');
      },
      afterSession: async received => {
        expect(received).toBe(session);
        calls.push('afterSession');
      },
    },
  });

  await expect(orchestrator.processMessage(session)).rejects.toBe(failure);
  expect(calls).toEqual(['beforeSession', 'onError', 'afterSession']);
});
